using System.Text;
using PcTidy.Core;
using PcTidy.Hosting;
using PcTidy.TestbedGen;
using Xunit;

namespace PcTidy.Features.Search.Tests;

[CollectionDefinition("search-testbed", DisableParallelization = true)]
public class SearchTestbedCollection { }

/// <summary>
/// One fake PC per test under testbed\search\, with the real composition root in sandbox mode (real SafetyGuard,
/// Executor and Undo). Generated by TestbedBuilder, or a bare tree for a specific layout. Deleted afterwards.
/// </summary>
internal sealed class SearchSandbox : IDisposable
{
    public static readonly string TestbedRoot = Path.Combine(FindCodeRoot(), "testbed", "search");
    public static readonly DateTime Now = new(2026, 11, 10, 12, 0, 0, DateTimeKind.Utc);

    private readonly bool _generated;

    public SearchSandbox(string name, SandboxProfile? profile = null, bool generate = false)
    {
        Profile = profile ?? SandboxProfile.Default;
        Root = Path.Combine(TestbedRoot, $"{name}-{Guid.NewGuid().ToString("N")[..6]}");
        _generated = generate;
        if (generate) TestbedBuilder.Generate(Root, TestbedSize.Small, Profile, new TestbedOptions { AnchorUtc = Now });
        else
        {
            Directory.CreateDirectory(Root);
            var k0 = new SandboxKnownLocations(Root, Profile);
            foreach (var d in k0.FixedDrives) Directory.CreateDirectory(d);
            foreach (var f in new[] { k0.Downloads, k0.Videos, k0.Music, k0.Pictures, k0.Documents, k0.Desktop, k0.LocalAppData, k0.WindowsDir, k0.ProgramFiles, k0.ProgramData })
                Directory.CreateDirectory(f);
            foreach (var c in k0.CloudRoots) Directory.CreateDirectory(c);
        }
        Host = PcTidyHost.CreateSandbox(Root, Profile);
        K = (SandboxKnownLocations)Host.Locations;
    }

    public string Root { get; }
    public SandboxProfile Profile { get; }
    public PcTidyHost Host { get; }
    public SandboxKnownLocations K { get; }
    public string D => K.FixedDrives.Count > 1 ? PathUtil.Normalize(K.FixedDrives[1]) : throw new InvalidOperationException("one-drive profile");

    public string Put(string path, string text, DateTime? writtenUtc = null) => Put(path, Encoding.UTF8.GetBytes(text), writtenUtc);

    public string Put(string path, byte[] bytes, DateTime? writtenUtc = null)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllBytes(path, bytes);
        if (writtenUtc is { } w)
        {
            File.SetCreationTimeUtc(path, w);
            File.SetLastWriteTimeUtc(path, w);
        }
        return path;
    }

    public void Dispose()
    {
        Host.Dispose();
        try
        {
            if (_generated) TestbedBuilder.Delete(Root);
            else ForceDelete(Root);
        }
        catch { /* best effort: the testbed folder is disposable */ }
    }

    internal static void ForceDelete(string dir)
    {
        if (!Directory.Exists(dir)) return;
        foreach (var d in Directory.EnumerateDirectories(dir, "*", new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = 0 }).ToList())
            if (Directory.Exists(d) && (File.GetAttributes(d) & FileAttributes.ReparsePoint) != 0) Directory.Delete(d);
        foreach (var f in Directory.EnumerateFiles(dir, "*", SearchOption.AllDirectories)) File.SetAttributes(f, FileAttributes.Normal);
        Directory.Delete(dir, recursive: true);
    }

    internal static string FindCodeRoot()
    {
        var d = new DirectoryInfo(AppContext.BaseDirectory);
        while (d != null && !File.Exists(Path.Combine(d.FullName, "PcTidy.sln"))) d = d.Parent;
        return d?.FullName ?? throw new InvalidOperationException("PcTidy.sln not found");
    }
}

/// <summary>A clock the test moves by hand (for debounce, dm: and periodic re-scan tests).</summary>
internal sealed class ManualClock(DateTimeOffset start, TimeZoneInfo? zone = null) : TimeProvider
{
    private DateTimeOffset _now = start;
    public override DateTimeOffset GetUtcNow() => _now;
    public override TimeZoneInfo LocalTimeZone { get; } = zone ?? TimeZoneInfo.Utc;
    public void Advance(TimeSpan by) => _now += by;

    /// <summary>No real timer: tests drive ticks themselves, so nothing races them.</summary>
    public override ITimer CreateTimer(TimerCallback callback, object? state, TimeSpan dueTime, TimeSpan period) => new NoTimer();

    private sealed class NoTimer : ITimer
    {
        public bool Change(TimeSpan dueTime, TimeSpan period) => true;
        public void Dispose() { }
        public ValueTask DisposeAsync() => ValueTask.CompletedTask;
    }
}

/// <summary>Runs a block under another culture (e.g. tr-TR, where "I".ToLower() isn't "i").</summary>
internal sealed class CultureScope : IDisposable
{
    private readonly System.Globalization.CultureInfo _culture, _ui;

    public CultureScope(string name)
    {
        _culture = System.Globalization.CultureInfo.CurrentCulture;
        _ui = System.Globalization.CultureInfo.CurrentUICulture;
        System.Globalization.CultureInfo.CurrentCulture = System.Globalization.CultureInfo.CurrentUICulture = new System.Globalization.CultureInfo(name);
    }

    public void Dispose()
    {
        System.Globalization.CultureInfo.CurrentCulture = _culture;
        System.Globalization.CultureInfo.CurrentUICulture = _ui;
    }
}
